 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    bars = Counter()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            seen[r][c] = True
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            bars[color] += 1
    out = []
    for color in (3, 2):
        out.extend([color] * bars[color])
    return [out[i:i + 3] + [0] * max(0, 3 - len(out[i:i + 3])) for i in range(0, 6, 3)]
